#!/bin/bash
# DLT-dyn on PEMS08: input 96, horizons 12 24 48 96; the stand-alone recipe of the paper (src/configs/dlt_profiles.py).
# Generated by scripts/multivariate_forecasting/make_scripts.py: change the profile and generate again.
#   bash scripts/multivariate_forecasting/PEMS/DLT_PEMS08.sh                                   seeds 2021 2022 2023
#   SEEDS="2021" EXTRA_ARGS="--no_use_gpu --num_workers 0" bash scripts/multivariate_forecasting/PEMS/DLT_PEMS08.sh   one seed on the CPU
# Results: output/long_term_forecast/PEMS08.tsv (one row per run); checkpoints: temp/checkpoints/PEMS08/.
export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
cd "$(dirname "$0")/../../.."
root="$(python -m src.utils.paths root PEMS08.npz)/"
seeds=(${SEEDS:-2021 2022 2023})

for pred_len in 12 24 48 96; do
  for seed in "${seeds[@]}"; do
    python -u scripts/run.py \
      --is_training 1 \
      --model DLT \
      --des "PEMS08_${pred_len}_dltdyn" \
      --seed "$seed" \
      --root_path "$root" \
      --data_path PEMS08.npz \
      --data PEMS \
      --model_id "PEMS08_96_$pred_len" \
      --features M \
      --seq_len 96 \
      --label_len 0 \
      --pred_len "$pred_len" \
      --enc_in 170 \
      --dec_in 170 \
      --c_out 170 \
      --freq h \
      --dlt_variant dltdyn \
      --dlt_k 8 \
      --dlt_L 48 \
      --dlt_R 4 \
      --dlt_impl basis \
      --learning_rate 0.003 \
      --batch_size 32 \
      --train_epochs 10 \
      --patience 3 \
      --drop_last \
      --test_batch_size 1 \
      --no_time_marks \
      $EXTRA_ARGS
  done
done
